const WPT_IN_PROCESS_PARALLELISM: usize = 4;

macro_rules! wpt_compat_cases {
    ($($test_name:ident => $case_id:literal,)+) => {
        const DEFAULT_WPT_COMPAT_CASE_IDS: &[&str] = &[$($case_id,)+];

        $(
            #[test]
            fn $test_name() -> Result<()> {
                wpt_async_runtime().block_on(run_wpt_compat_case($case_id))
            }
        )+
    };
}

macro_rules! wpt_explicit_default_excluded_cases {
    ($($test_name:ident => $case_id:literal,)+) => {
        const EXPLICIT_DEFAULT_EXCLUDED_WPT_CASE_IDS: &[&str] = &[$($case_id,)+];

        $(
            #[test]
            #[ignore = "requires explicit WPT selection; case is intentionally outside default nextest health"]
            fn $test_name() -> Result<()> {
                wpt_async_runtime().block_on(run_explicit_wpt_compat_case($case_id))
            }
        )+
    };
}

