#[test]
fn wpt_compat_rust_entrypoints_match_manifest_selection() -> Result<()> {
    use std::collections::BTreeSet;

    use moli_wpt_compat::{
        COMPOSITOR_BEHAVIOR_TAG, DEFAULT_EXCLUDED_WPT_TAGS, HARNESS_BLOCKED_TAG,
        LAYOUT_GEOMETRY_BEHAVIOR_TAG, MEDIA_FIDELITY_BEHAVIOR_TAG, REAL_LAYOUT_BEHAVIOR_TAG,
        VISUAL_RENDERING_BEHAVIOR_TAG, WptManifestScope, parse_manifest, select_manifest_tests,
    };

    let manifest = include_str!("../../moli-wpt-compat/fixtures/wpt/manifest.toml");
    let manifest_tests = parse_manifest(manifest)?;
    for tag in [
        LAYOUT_GEOMETRY_BEHAVIOR_TAG,
        VISUAL_RENDERING_BEHAVIOR_TAG,
        REAL_LAYOUT_BEHAVIOR_TAG,
        COMPOSITOR_BEHAVIOR_TAG,
        MEDIA_FIDELITY_BEHAVIOR_TAG,
        HARNESS_BLOCKED_TAG,
    ] {
        assert!(
            DEFAULT_EXCLUDED_WPT_TAGS.contains(&tag),
            "explicit-only WPT tag '{tag}' must stay outside default nextest selection"
        );
    }

    let default_manifest_ids = select_manifest_tests(
        manifest_tests.clone(),
        WptManifestScope::All,
        BTreeSet::new(),
        BTreeSet::new(),
    )?
    .into_iter()
    .map(|test| test.id)
    .collect::<BTreeSet<_>>();
    let default_entrypoint_ids = case_id_set(DEFAULT_WPT_COMPAT_CASE_IDS);
    assert_case_id_sets_match(
        "default WPT compat",
        &default_manifest_ids,
        &default_entrypoint_ids,
    );

    let explicit_manifest_ids = manifest_tests
        .iter()
        .filter(|test| {
            test.tags
                .iter()
                .any(|tag| DEFAULT_EXCLUDED_WPT_TAGS.contains(&tag.as_str()))
        })
        .map(|test| test.id.clone())
        .collect::<BTreeSet<_>>();
    assert!(
        !explicit_manifest_ids.is_empty(),
        "manifest should retain explicit-only WPT investigation cases"
    );
    let explicit_entrypoint_ids = case_id_set(EXPLICIT_DEFAULT_EXCLUDED_WPT_CASE_IDS);
    assert_case_id_sets_match(
        "explicit-only WPT compat",
        &explicit_manifest_ids,
        &explicit_entrypoint_ids,
    );

    Ok(())
}

fn case_id_set(ids: &[&str]) -> std::collections::BTreeSet<String> {
    ids.iter().map(|id| (*id).to_owned()).collect()
}

fn assert_case_id_sets_match(
    label: &str,
    manifest_ids: &std::collections::BTreeSet<String>,
    entrypoint_ids: &std::collections::BTreeSet<String>,
) {
    let missing_entrypoints = manifest_ids.difference(entrypoint_ids).collect::<Vec<_>>();
    let extra_entrypoints = entrypoint_ids.difference(manifest_ids).collect::<Vec<_>>();
    assert!(
        missing_entrypoints.is_empty() && extra_entrypoints.is_empty(),
        "{label} Rust WPT entrypoints are out of sync with manifest selection\nmissing entrypoints for manifest ids: {missing_entrypoints:#?}\nextra entrypoints not selected by manifest: {extra_entrypoints:#?}"
    );
}

async fn run_wpt_compat_case(case_id: &'static str) -> Result<()> {
    ensure_workspace_current_dir()?;
    let _permit = wpt_case_semaphore().acquire().await?;

    let Some(report) = run_selected_wpt_case(case_id).await? else {
        return Ok(());
    };
    assert_wpt_report(&report, case_id)
}

async fn run_explicit_wpt_compat_case(case_id: &'static str) -> Result<()> {
    ensure_workspace_current_dir()?;
    let _permit = wpt_case_semaphore().acquire().await?;

    let Some(report) = run_exact_wpt_case(case_id).await? else {
        return Err(anyhow!("WPT case '{case_id}' is not present in manifest"));
    };
    assert_wpt_report(&report, case_id)
}

fn wpt_case_semaphore() -> &'static Semaphore {
    static SEMAPHORE: OnceLock<Semaphore> = OnceLock::new();
    SEMAPHORE.get_or_init(|| Semaphore::new(WPT_IN_PROCESS_PARALLELISM))
}

fn wpt_async_runtime() -> &'static tokio::runtime::Runtime {
    static RUNTIME: OnceLock<tokio::runtime::Runtime> = OnceLock::new();
    RUNTIME.get_or_init(|| {
        tokio::runtime::Builder::new_multi_thread()
            .enable_all()
            .worker_threads(WPT_IN_PROCESS_PARALLELISM)
            .thread_name("wpt-compat")
            .build()
            .expect("failed to build WPT compat Tokio runtime")
    })
}

async fn run_selected_wpt_case(case_id: &str) -> Result<Option<WptSuiteReport>> {
    let server = WptFixtureServer::spawn().await?;
    let report = wpt_support::run_selected_case(&server, case_id).await;
    server.shutdown().await;
    report
}

async fn run_exact_wpt_case(case_id: &str) -> Result<Option<WptSuiteReport>> {
    let server = WptFixtureServer::spawn().await?;
    let report = wpt_support::run_exact_case(&server, case_id).await;
    server.shutdown().await;
    report
}

fn ensure_workspace_current_dir() -> Result<()> {
    static CWD_RESULT: OnceLock<std::result::Result<(), String>> = OnceLock::new();
    CWD_RESULT
        .get_or_init(|| {
            let workspace_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .parent()
                .ok_or_else(|| {
                    "moli-core manifest dir should have a workspace parent".to_owned()
                })?;
            std::env::set_current_dir(workspace_root)
                .map_err(|error| format!("failed to set workspace cwd: {error}"))
        })
        .as_ref()
        .map_err(|error| anyhow!(error.clone()))
        .copied()
}

fn assert_wpt_report(report: &WptSuiteReport, case_id: &str) -> Result<()> {
    let summary = report.summary();
    let report_label = format!("wpt-compat-{case_id}");
    let report_path = report.write_summary_json_with_label(&report_label)?;
    let markdown_report_path = report.write_markdown_report_with_label(&report_label)?;
    if summary.total != 1
        || summary.unexpected_fail != 0
        || summary.unexpected_pass != 0
        || summary.skip != 0
        || summary.pass + summary.known_fail != 1
    {
        return Err(anyhow!(
            "WPT case '{case_id}' summary did not match default health expectations\n{}\n\n{}",
            summary.to_markdown(),
            report
                .assert_no_unexpected_failures()
                .expect_err("non-passing summary should expose report failures")
        ));
    }
    assert!(report_path.ends_with(format!("moli-wpt-compat-report-{report_label}.json")));
    assert!(report_path.exists());
    let report_json = std::fs::read_to_string(&report_path)?;
    let report_json: serde_json::Value = serde_json::from_str(&report_json)?;
    assert_eq!(report_json["summary"]["total"], summary.total);
    assert_eq!(
        report_json["cases"].as_array().map(|cases| cases.len()),
        Some(summary.total)
    );
    assert!(markdown_report_path.ends_with(format!("moli-wpt-compat-report-{report_label}.md")));
    assert!(markdown_report_path.exists());
    let markdown_report = std::fs::read_to_string(&markdown_report_path)?;
    assert!(markdown_report.contains("# WPT Compat Report"));
    assert!(
        markdown_report
            .contains("| total | pass | known-fail | unexpected-fail | unexpected-pass | skip |")
    );
    assert!(markdown_report.contains(&format!(
        "| {} | {} | {} | {} | {} | {} |",
        summary.total,
        summary.pass,
        summary.known_fail,
        summary.unexpected_fail,
        summary.unexpected_pass,
        summary.skip,
    )));
    assert!(markdown_report.contains("## Case Inventory"));
    report.assert_no_unexpected_failures()
}
